fn process_refresh_obligation(program_id: &Pubkey, accounts: &[AccountInfo]) -> ProgramResult {
    let mut obligation = Obligation::unpack(&obligation_info.data.borrow())?;

    let mut deposited_value: u128 = 0;
    let mut borrowed_value: u128 = 0;

    for (index, collateral) in obligation.deposits.iter_mut().enumerate() {
        let deposit_reserve = Reserve::unpack(&deposit_reserve_info.data.borrow())?;

        let decimals = 10u64.pow(deposit_reserve.liquidity.mint_decimals as u32);

        let market_value = (collateral.deposited_amount as u128)
            * (deposit_reserve.liquidity.market_price as u128)
            / (decimals as u128);

        deposited_value += market_value;
    }

    obligation.deposited_value = deposited_value;
    obligation.borrowed_value = borrowed_value;
    Obligation::pack(obligation, &mut obligation_info.data.borrow_mut())?;
    Ok(())
}

pub fn mint<'a>(
    token_program_id: AccountInfo<'a>,
    mint_account: AccountInfo<'a>,
    destination_account: AccountInfo<'a>,
    authority_account: AccountInfo<'a>,
    amount: u64,
    pool_pub_key: &Pubkey,
    bump_seed: u8,
) -> ProgramResult {
    let me_bytes = pool_pub_key.to_bytes();
    let authority_signature_seeds = [&me_bytes[..32], &[bump_seed]];
    let signers = &[&authority_signature_seeds[..]];

    let ix = spl_token::instruction::mint_to(
        token_program_id.key,
        mint_account.key,
        destination_account.key,
        authority_account.key,
        &[authority_account.key],
        amount,
    )?;

    invoke_signed(
        &ix,
        &[token_program_id, mint_account, destination_account, authority_account],
        signers,
    )
}

fn process_propose(program_id: &Pubkey, accounts: &[AccountInfo],
    tokens_to_mint: u64, acceptance_criteria: AcceptanceCriteria,
    mint_bump: u8, feature_id_bump: u8,
) -> ProgramResult {
    let mint_address = Pubkey::create_program_address(
        &[&feature_proposal_info.key.to_bytes(), br"mint", &[mint_bump]],
        program_id,
    )?;
    if mint_address != *mint_info.key {
        return Err(ProgramError::InvalidArgument);
    }

    let feature_id_address = Pubkey::create_program_address(
        &[&feature_proposal_info.key.to_bytes(), br"feature-id", &[feature_id_bump]],
        program_id,
    )?;
    if feature_id_address != *feature_id_info.key {
        return Err(ProgramError::InvalidArgument);
    }
    Ok(())
}

fn process_add_validator_to_pool(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    raw_validator_seed: u32,
) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let stake_pool_info = next_account_info(account_info_iter)?;
    let validator_list_info = next_account_info(account_info_iter)?;
    let validator_vote_info = next_account_info(account_info_iter)?;

    let stake_pool = try_from_slice_unchecked::<StakePool>(&stake_pool_info.data.borrow())?;
    let mut validator_list_data = validator_list_info.data.borrow_mut();
    let (header, mut validator_list) = ValidatorListHeader::deserialize_vec(&mut validator_list_data)?;

    validator_list.push(ValidatorStakeInfo {
        status: StakeStatus::Active.into(),
        vote_account_address: *validator_vote_info.key,
        active_stake_lamports: 0.into(),
        transient_stake_lamports: 0.into(),
        last_update_epoch: 0.into(),
        transient_seed_suffix: 0.into(),
        unused: 0.into(),
        validator_seed_suffix: raw_validator_seed.into(),
    })?;
    Ok(())
}

pub fn process_withdraw(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    amount: u64,
) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let pool_account_info = next_account_info(account_info_iter)?;
    let authority_account_info = next_account_info(account_info_iter)?;
    let user_transfer_authority_info = next_account_info(account_info_iter)?;
    let pool_deposit_token_account_info = next_account_info(account_info_iter)?;
    let token_pass_user_account_info = next_account_info(account_info_iter)?;
    let token_pass_mint_info = next_account_info(account_info_iter)?;
    let user_token_destination_info = next_account_info(account_info_iter)?;
    let token_program_info = next_account_info(account_info_iter)?;

    if amount == 0 {
        return Err(PoolError::InvalidAmount.into());
    }

    let pool = Pool::try_from_slice(&pool_account_info.data.borrow())?;
    if pool.token_pass_mint != *token_pass_mint_info.key {
        return Err(PoolError::InvalidTokenMint.into());
    }

    let authority_pub_key = Self::authority_id(program_id, pool_account_info.key, pool.bump_seed)?;
    if *authority_account_info.key != authority_pub_key {
        return Err(PoolError::InvalidAuthorityAccount.into());
    }

    // FIRST: Burn user's PASS tokens (destroys withdrawal authorization)
    Self::burn(
        token_program_info.clone(), token_pass_user_account_info.clone(),
        token_pass_mint_info.clone(), authority_account_info.clone(),
        user_transfer_authority_info.clone(), amount, pool_account_info.key, pool.bump_seed,
    )?;

    // THEN: Transfer deposit tokens back to user
    Self::transfer(
        token_program_info.clone(), pool_deposit_token_account_info.clone(),
        user_token_destination_info.clone(), authority_account_info.clone(),
        authority_account_info.clone(), amount, pool_account_info.key, pool.bump_seed,
    )?;

    Ok(())
}

pub fn process_mint_to(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    amount: u64,
    instruction_variant: InstructionVariant,
) -> ProgramResult {
    check_program_account(mint_info.owner)?;
    check_program_account(destination_account_info.owner)?;

    if destination_account.base.is_frozen() {
        return Err(TokenError::AccountFrozen.into());
    }
    if destination_account.base.is_native() {
        return Err(TokenError::NativeNotSupported.into());
    }
    if mint_info.key != &destination_account.base.mint {
        return Err(TokenError::MintMismatch.into());
    }

    match &mint.base.mint_authority {
        PodCOption { option: PodCOption::<Pubkey>::SOME, value: mint_authority } =>
            Self::validate_owner(program_id, mint_authority, owner_info,
                owner_info_data_len, account_info_iter.as_slice())?,
        _ => return Err(TokenError::FixedSupply.into()),
    }

    destination_account.base.amount = u64::from(destination_account.base.amount)
        .checked_add(amount)
        .ok_or(TokenError::Overflow)?
        .into();
    mint.base.supply = u64::from(mint.base.supply)
        .checked_add(amount)
        .ok_or(TokenError::Overflow)?
        .into();
    Ok(())
}

