pub fn process_transfer(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    amount: u64,
    expected_decimals: Option<u8>,
) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let source_account_info = next_account_info(account_info_iter)?;
    let expected_mint_info = if let Some(expected_decimals) = expected_decimals {
        Some((next_account_info(account_info_iter)?, expected_decimals))
    } else {
        None
    };
    let destination_account_info = next_account_info(account_info_iter)?;
    let authority_info = next_account_info(account_info_iter)?;

    let mut source_account = Account::unpack(&source_account_info.data.borrow())?;
    let mut destination_account = Account::unpack(&destination_account_info.data.borrow())?;

    if source_account.is_frozen() || destination_account.is_frozen() {
        return Err(TokenError::AccountFrozen.into());
    }
    if source_account.amount < amount {
        return Err(TokenError::InsufficientFunds.into());
    }
    if !Self::cmp_pubkeys(&source_account.mint, &destination_account.mint) {
        return Err(TokenError::MintMismatch.into());
    }

    match source_account.delegate {
        COption::Some(ref delegate) if Self::cmp_pubkeys(authority_info.key, delegate) => {
            Self::validate_owner(program_id, delegate, authority_info, account_info_iter.as_slice())?;
            if source_account.delegated_amount < amount {
                return Err(TokenError::InsufficientFunds.into());
            }
            source_account.delegated_amount = source_account.delegated_amount
                .checked_sub(amount).ok_or(TokenError::Overflow)?;
        }
        _ => Self::validate_owner(program_id, &source_account.owner, authority_info, account_info_iter.as_slice())?,
    };

    source_account.amount = source_account.amount.checked_sub(amount).ok_or(TokenError::Overflow)?;
    destination_account.amount = destination_account.amount.checked_add(amount).ok_or(TokenError::Overflow)?;

    Account::pack(source_account, &mut source_account_info.data.borrow_mut())?;
    Account::pack(destination_account, &mut destination_account_info.data.borrow_mut())?;
    Ok(())
}

pub fn process_decide(
    _program_id: &Pubkey,
    accounts: &[AccountInfo],
    decision: bool,
) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let pool_account_info = next_account_info(account_info_iter)?;
    let decider_account_info = next_account_info(account_info_iter)?;
    let clock_info = next_account_info(account_info_iter)?;
    let clock = &Clock::from_account_info(clock_info)?;

    let mut pool = Pool::try_from_slice(&pool_account_info.data.borrow())?;

    if *decider_account_info.key != pool.decider {
        return Err(PoolError::WrongDeciderAccount.into());
    }

    if !decider_account_info.is_signer {
        return Err(PoolError::SignatureMissing.into());
    }

    if pool.decision != Decision::Undecided {
        return Err(PoolError::DecisionAlreadyMade.into());
    }

    let current_slot = clock.slot;
    if current_slot < pool.mint_end_slot || current_slot > pool.decide_end_slot {
        return Err(PoolError::InvalidSlotForDecision.into());
    }

    pool.decision = if decision { Decision::Pass } else { Decision::Fail };
    borsh::to_writer(&mut pool_account_info.data.borrow_mut()[..], &pool)?;
    Ok(())
}

fn process_propose(program_id: &Pubkey, accounts: &[AccountInfo]) -> ProgramResult {
    let (mint_address, mint_bump_seed) = get_mint_address_with_seed(feature_proposal_info.key);
    if mint_address != *mint_info.key {
        return Err(ProgramError::InvalidArgument);
    }

    let (distributor_token_address, distributor_token_bump_seed) =
        get_distributor_token_address_with_seed(feature_proposal_info.key);
    if distributor_token_address != *distributor_token_info.key {
        return Err(ProgramError::InvalidArgument);
    }

    let (acceptance_token_address, acceptance_token_bump_seed) =
        get_acceptance_token_address_with_seed(feature_proposal_info.key);
    if acceptance_token_address != *acceptance_token_info.key {
        return Err(ProgramError::InvalidArgument);
    }

    let (feature_id_address, feature_id_bump_seed) =
        get_feature_id_address_with_seed(feature_proposal_info.key);
    if feature_id_address != *feature_id_info.key {
        return Err(ProgramError::InvalidArgument);
    }
    Ok(())
}

fn relocate_lamports(
    source_account_info: &AccountInfo,
    destination_account_info: &AccountInfo,
    lamports: u64,
) -> ProgramResult {
    {
        let mut source_lamports = source_account_info.try_borrow_mut_lamports()?;
        **source_lamports = source_lamports
            .checked_sub(lamports)
            .ok_or(ProgramError::InsufficientFunds)?;
    }
    {
        let mut destination_lamports = destination_account_info.try_borrow_mut_lamports()?;
        **destination_lamports = destination_lamports
            .checked_add(lamports)
            .ok_or(ProgramError::ArithmeticOverflow)?;
    }
    Ok(())
}

RecordInstruction::Reallocate { data_length } => {
    let data_info = next_account_info(account_info_iter)?;
    let authority_info = next_account_info(account_info_iter)?;
    {
        let raw_data = &mut data_info.data.borrow_mut();
        let account_data = bytemuck::try_from_bytes_mut::<RecordData>(
            &mut raw_data[..RecordData::WRITABLE_START_INDEX],
        ).map_err(|_| ProgramError::InvalidArgument)?;
        if !account_data.is_initialized() {
            return Err(ProgramError::UninitializedAccount);
        }
        check_authority(authority_info, &account_data.authority)?;
    }

    let needed_account_length = std::mem::size_of::<RecordData>()
        .checked_add(usize::try_from(data_length).map_err(|_| ProgramError::InvalidArgument)?)
        .unwrap();

    if data_info.data_len() >= needed_account_length {
        return Ok(());
    }
    data_info.resize(needed_account_length)?;
    Ok(())
}

pub fn process_mint_to(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    amount: u64,
) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let mint_info = next_account_info(account_info_iter)?;
    let destination_account_info = next_account_info(account_info_iter)?;
    let owner_info = next_account_info(account_info_iter)?;

    let mut destination_account = Account::unpack(&destination_account_info.data.borrow())?;
    let mut mint = Mint::unpack(&mint_info.data.borrow())?;

    destination_account.amount += amount;
    mint.supply += amount;

    Account::pack(destination_account, &mut destination_account_info.data.borrow_mut())?;
    Mint::pack(mint, &mut mint_info.data.borrow_mut())?;
    Ok(())
}

pub fn process_deposit_governing_tokens(
    program_id: &Pubkey, accounts: &[AccountInfo], amount: u64,
) -> ProgramResult {
    let realm_data = get_realm_data(program_id, realm_info)?;
    realm_data.assert_is_valid_governing_token_mint_and_holding(
        program_id, realm_info.key, &governing_token_mint, governing_token_holding_info.key)?;

    // WRONG: Create/update record FIRST
    let mut record = get_token_owner_record_data_for_seeds(
        program_id, token_owner_record_info, &token_owner_record_address_seeds)?;
    record.governing_token_deposit_amount = record.governing_token_deposit_amount
        .checked_add(amount).unwrap();
    record.serialize(&mut token_owner_record_info.data.borrow_mut()[..])?;

    // THEN transfer tokens — but voting power already granted
    transfer_spl_tokens(
        governing_token_source_info, governing_token_holding_info,
        governing_token_source_authority_info, amount, spl_token_info)?;
    Ok(())
}

pub fn process_swap(
    program_id: &Pubkey, amount_in: u64, minimum_amount_out: u64,
    accounts: &[AccountInfo],
) -> ProgramResult {
    if swap_info.owner != program_id {
        return Err(ProgramError::IncorrectProgramId);
    }
    let token_swap = SwapVersion::unpack(&swap_info.data.borrow())?;

    if *authority_info.key != Self::authority_id(program_id, swap_info.key, token_swap.bump_seed())? {
        return Err(SwapError::InvalidProgramAddress.into());
    }
    if !(*swap_source_info.key == *token_swap.token_a_account()
        || *swap_source_info.key == *token_swap.token_b_account()) {
        return Err(SwapError::IncorrectSwapAccount.into());
    }
    if *swap_source_info.key == *swap_destination_info.key {
        return Err(SwapError::InvalidInput.into());
    }
    if *pool_mint_info.key != *token_swap.pool_mint() {
        return Err(SwapError::IncorrectPoolMint.into());
    }
    if *pool_fee_account_info.key != *token_swap.pool_fee_account() {
        return Err(SwapError::IncorrectFeeAccount.into());
    }

    if amount_received < minimum_amount_out {
        return Err(SwapError::ExceededSlippage.into());
    }
    Ok(())
}

fn process_set_manager(program_id: &Pubkey, accounts: &[AccountInfo]) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let stake_pool_info = next_account_info(account_info_iter)?;
    let manager_info = next_account_info(account_info_iter)?;
    let new_manager_info = next_account_info(account_info_iter)?;
    let new_manager_fee_info = next_account_info(account_info_iter)?;

    check_account_owner(stake_pool_info, program_id)?;
    let mut stake_pool = try_from_slice_unchecked::<StakePool>(&stake_pool_info.data.borrow())?;
    check_account_owner(new_manager_fee_info, &stake_pool.token_program_id)?;
    if !stake_pool.is_valid() {
        return Err(StakePoolError::InvalidState.into());
    }

    stake_pool.check_manager(manager_info)?;
    if !new_manager_info.is_signer {
        msg!("New manager signature missing");
        return Err(StakePoolError::SignatureMissing.into());
    }

    stake_pool.check_manager_fee_info(new_manager_fee_info)?;

    stake_pool.manager = *new_manager_info.key;
    stake_pool.manager_fee_account = *new_manager_fee_info.key;
    borsh::to_writer(&mut stake_pool_info.data.borrow_mut()[..], &stake_pool)?;
    Ok(())
}

fn process_set_preferred_validator(
    program_id: &Pubkey, accounts: &[AccountInfo],
    validator_type: PreferredValidatorType, validator_vote_address: Option<Pubkey>,
) -> ProgramResult {
    let mut stake_pool = try_from_slice_unchecked::<StakePool>(&stake_pool_info.data.borrow())?;

    match validator_type {
        PreferredValidatorType::Deposit => stake_pool.preferred_deposit_validator_vote_address = validator_vote_address,
        PreferredValidatorType::Withdraw => stake_pool.preferred_withdraw_validator_vote_address = validator_vote_address,
    }
    stake_pool.serialize(&mut stake_pool_info.data.borrow_mut())?;
    Ok(())
}

pub fn process_withdraw(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    amount: u64,
) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let pool_account_info = next_account_info(account_info_iter)?;
    let authority_account_info = next_account_info(account_info_iter)?;
    let user_transfer_authority_info = next_account_info(account_info_iter)?;
    let pool_deposit_token_account_info = next_account_info(account_info_iter)?;
    let token_pass_user_account_info = next_account_info(account_info_iter)?;
    let token_fail_user_account_info = next_account_info(account_info_iter)?;
    let token_pass_mint_info = next_account_info(account_info_iter)?;
    let token_fail_mint_info = next_account_info(account_info_iter)?;
    let user_token_destination_info = next_account_info(account_info_iter)?;
    let token_program_info = next_account_info(account_info_iter)?;

    let user_pass_token_account = Account::unpack(&token_pass_user_account_info.data.borrow())?;
    let user_fail_token_account = Account::unpack(&token_fail_user_account_info.data.borrow())?;
    let pool = Pool::try_from_slice(&pool_account_info.data.borrow())?;

    let possible_withdraw_amount = amount
        .min(user_pass_token_account.amount)
        .min(user_fail_token_account.amount);

    // Burns PASS tokens using min amount
    Self::burn(token_program_info.clone(), token_pass_user_account_info.clone(),
        token_pass_mint_info.clone(), authority_account_info.clone(),
        user_transfer_authority_info.clone(), possible_withdraw_amount,
        pool_account_info.key, pool.bump_seed,
    )?;

    // BUG: Burns FAIL tokens using original amount, not possible_withdraw_amount
    Self::burn(token_program_info.clone(), token_fail_user_account_info.clone(),
        token_fail_mint_info.clone(), authority_account_info.clone(),
        user_transfer_authority_info.clone(), amount,
        pool_account_info.key, pool.bump_seed,
    )?;

    // Transfers original amount, not possible_withdraw_amount
    Self::transfer(token_program_info.clone(), pool_deposit_token_account_info.clone(),
        user_token_destination_info.clone(), authority_account_info.clone(),
        authority_account_info.clone(), amount,
        pool_account_info.key, pool.bump_seed,
    )?;

    Ok(())
}

fn process_init_lending_market(
    program_id: &Pubkey,
    owner: Pubkey,
    quote_currency: [u8; 32],
    accounts: &[AccountInfo],
) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let lending_market_info = next_account_info(account_info_iter)?;
    let rent = &Rent::from_account_info(next_account_info(account_info_iter)?)?;
    let token_program_id = next_account_info(account_info_iter)?;
    let oracle_program_id = next_account_info(account_info_iter)?;

    assert_rent_exempt(rent, lending_market_info)?;
    let mut lending_market = assert_uninitialized::<LendingMarket>(lending_market_info)?;
    if lending_market_info.owner != program_id {
        return Err(LendingError::InvalidAccountOwner.into());
    }

    lending_market.init(InitLendingMarketParams {
        bump_seed: Pubkey::find_program_address(&[lending_market_info.key.as_ref()], program_id).1,
        owner,
        quote_currency,
        token_program_id: *token_program_id.key,
        oracle_program_id: *oracle_program_id.key,
    });
    LendingMarket::pack(lending_market, &mut lending_market_info.data.borrow_mut())?;
    Ok(())
}

pub fn process_burn(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    amount: u64,
) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let source_account_info = next_account_info(account_info_iter)?;
    let mint_info = next_account_info(account_info_iter)?;
    let authority_info = next_account_info(account_info_iter)?;

    let mut source_account = Account::unpack(&source_account_info.data.borrow())?;
    let mut mint = Mint::unpack(&mint_info.data.borrow())?;

    if source_account.amount < amount {
        return Err(TokenError::InsufficientFunds.into());
    }

    source_account.amount = source_account.amount.checked_sub(amount).ok_or(TokenError::Overflow)?;
    mint.supply = mint.supply.checked_sub(amount).ok_or(TokenError::Overflow)?;

    Account::pack(source_account, &mut source_account_info.data.borrow_mut())?;
    Mint::pack(mint, &mut mint_info.data.borrow_mut())?;
    Ok(())
}

fn process_initialize_pool(program_id: &Pubkey, accounts: &[AccountInfo],
    pool_bump: u8, stake_bump: u8, mint_bump: u8,
    stake_auth_bump: u8, mint_auth_bump: u8,
) -> ProgramResult {
    check_vote_account(vote_account_info)?;

    let pool_address = Pubkey::create_program_address(
        &[POOL_PREFIX, vote_account_info.key.as_ref(), &[pool_bump]], program_id)?;
    if pool_address != *pool_info.key {
        return Err(SinglePoolError::InvalidPoolAccount.into());
    }

    let stake_address = Pubkey::create_program_address(
        &[POOL_STAKE_PREFIX, pool_info.key.as_ref(), &[stake_bump]], program_id)?;
    if stake_address != *pool_stake_info.key {
        return Err(SinglePoolError::InvalidPoolStakeAccount.into());
    }

    check_system_program(system_program_info.key)?;
    check_token_program(token_program_info.key)?;
    check_stake_program(stake_program_info.key)?;
    Ok(())
}

pub fn process_recover_nested(program_id: &Pubkey, accounts: &[AccountInfo]) -> ProgramResult {
    let owner_associated_token_account_info = next_account_info(account_info_iter)?;
    let owner_token_mint_info = next_account_info(account_info_iter)?;
    let wallet_account_info = next_account_info(account_info_iter)?;
