pub fn process_execute_transaction(program_id: &Pubkey, accounts: &[AccountInfo]) -> ProgramResult {
    let proposal_transaction_data = get_proposal_transaction_data_for_proposal(
        program_id, proposal_transaction_info, proposal_info.key)?;

    let instructions = proposal_transaction_data.instructions.iter().map(Instruction::from);
    let instruction_account_infos = account_info_iter.as_slice();

    let governance_seeds = governance_data.get_governance_address_seeds()?.to_vec();

    for instruction in instructions {
        let _ = invoke_signed(&instruction, instruction_account_infos, &signers_seeds[..]);
    }

    proposal_transaction_data.execution_status = TransactionExecutionStatus::Success;
    proposal_transaction_data.serialize(&mut proposal_transaction_info.data.borrow_mut()[..])?;
    Ok(())
}

fn _process_initialize_multisig(
    accounts: &[AccountInfo],
    m: u8,
) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let multisig_info = next_account_info(account_info_iter)?;

    let mut multisig = Multisig::unpack_unchecked(&multisig_info.data.borrow())?;
    if multisig.is_initialized {
        return Err(TokenError::AlreadyInUse.into());
    }

    let signer_infos = account_info_iter.as_slice();
    multisig.m = m;
    multisig.n = signer_infos.len() as u8;
    for (i, signer_info) in signer_infos.iter().enumerate() {
        multisig.signers[i] = *signer_info.key;
    }
    multisig.is_initialized = true;

    Multisig::pack(multisig, &mut multisig_info.data.borrow_mut())?;
    Ok(())
}

fn process_accept_offer(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    maker_size: u64,
    taker_size: u64,
    bump_seed: u8,
) -> ProgramResult {
    let maker_src_token_account: spl_token::state::Account =
        spl_token::state::Account::unpack(&maker_src_account.data.borrow())?;

    if maker_src_token_account.delegated_amount != maker_pay_size {
        return Err(ProgramError::InvalidAccountData);
    }
    let authority_key = Pubkey::create_program_address(seeds, program_id)?;
    assert_keys_equal(authority_key, *transfer_authority.key)?;

    if maker_src_token_account.delegate != COption::Some(authority_key) {
        return Err(ProgramError::InvalidAccountData);
    }
    assert_keys_equal(spl_token::id(), *token_program_info.key)?;
    assert_is_ata(maker_src_account, maker_wallet.key, maker_src_mint.key)?;
    assert_is_ata(taker_dst_account, taker_wallet.key, maker_src_mint.key)?;
    Ok(())
}

fn process_deposit_reserve_liquidity(
    program_id: &Pubkey, liquidity_amount: u64, accounts: &[AccountInfo],
) -> ProgramResult {
    let mut reserve = Reserve::unpack(&reserve_info.data.borrow())?;
    let collateral_amount = reserve.deposit_liquidity(liquidity_amount)?;
    Reserve::pack(reserve, &mut reserve_info.data.borrow_mut())?;

    // WRONG: Mint collateral FIRST
    spl_token_mint_to(TokenMintToParams {
        mint: reserve_collateral_mint_info.clone(),
        destination: destination_collateral_info.clone(),
        amount: collateral_amount, authority: lending_market_authority_info.clone(),
        authority_signer_seeds, token_program: token_program_id.clone(),
    })?;

    // THEN transfer liquidity — but collateral already minted
    spl_token_transfer(TokenTransferParams {
        source: source_liquidity_info.clone(),
        destination: reserve_liquidity_supply_info.clone(),
        amount: liquidity_amount, authority: user_transfer_authority_info.clone(),
        authority_signer_seeds: &[], token_program: token_program_id.clone(),
    })?;
    Ok(())
}

pub fn process_cast_vote(
    program_id: &Pubkey, accounts: &[AccountInfo], vote: Vote,
) -> ProgramResult {
    if !vote_record_info.data_is_empty() {
        return Err(GovernanceError::VoteAlreadyExists.into());
    }

    let realm_data = get_realm_data_for_governing_token_mint(
        program_id, realm_info, vote_governing_token_mint_info.key)?;

    let mut proposal_data = get_proposal_data_for_governance_and_governing_mint(
        program_id, proposal_info, governance_info.key, &proposal_governing_token_mint)?;
    proposal_data.assert_can_cast_vote(&governance_data.config, &vote, clock.unix_timestamp)?;

    let mut voter_record = get_token_owner_record_data_for_realm_and_governing_mint(
        program_id, voter_token_owner_record_info, &governance_data.realm,
        vote_governing_token_mint_info.key)?;
    voter_record.assert_token_owner_or_delegate_is_signer(governance_authority_info)?;

    voter_record.unrelinquished_votes_count = voter_record
        .unrelinquished_votes_count.checked_add(1).unwrap();

    proposal_data.assert_valid_vote(&vote)?;
    Ok(())
}

pub fn process_deposit_all_token_types(
    program_id: &Pubkey,
    pool_token_amount: u64,
    maximum_token_a_amount: u64,
    maximum_token_b_amount: u64,
    accounts: &[AccountInfo],
) -> ProgramResult {
    let token_swap = SwapVersion::unpack(&swap_info.data.borrow())?;
    let calculator = &token_swap.swap_curve().calculator;
    if !calculator.allows_deposits() {
        return Err(SwapError::UnsupportedCurveOperation.into());
    }

    let token_a = Self::unpack_token_account(token_a_info, token_swap.token_program_id())?;
    let token_b = Self::unpack_token_account(token_b_info, token_swap.token_program_id())?;
    let pool_mint = Self::unpack_mint(pool_mint_info, token_swap.token_program_id())?;

    let results = calculator
        .pool_tokens_to_trading_tokens(
            u128::from(pool_token_amount),
            u128::from(pool_mint.supply),
            u128::from(token_a.amount),
            u128::from(token_b.amount),
            RoundDirection::Ceiling,
        )
        .ok_or(SwapError::ZeroTradingTokens)?;

    let token_a_amount = to_u64(results.token_a_amount)?;
    if token_a_amount > maximum_token_a_amount {
        return Err(SwapError::ExceededSlippage.into());
    }
    if token_a_amount == 0 {
        return Err(SwapError::ZeroTradingTokens.into());
    }
    let token_b_amount = to_u64(results.token_b_amount)?;
    if token_b_amount > maximum_token_b_amount {
        return Err(SwapError::ExceededSlippage.into());
    }
    if token_b_amount == 0 {
        return Err(SwapError::ZeroTradingTokens.into());
    }

    Ok(())
}

fn process_exchange(program_id: &Pubkey, accounts: &[AccountInfo]) -> ProgramResult {
    let original_account_data = original_account_info.try_borrow_data()?;
    let original_account = StateWithExtensions::<Account>::unpack(&original_account_data)?;
    let token_amount = original_account.base.amount;
    let decimals = original_mint.base.decimals;

    let _ = burn_original_tokens(original_token_program.clone(), original_account_info.clone(),
        original_mint_info.clone(), original_transfer_authority_info.clone(),
        account_info_iter.as_slice(), token_amount, decimals);

    transfer_new_tokens(new_token_program.clone(), new_escrow_info.clone(),
        new_mint_info.clone(), new_account_info.clone(), new_transfer_authority_info.clone(),
        &authority_seeds, token_amount, decimals)?;
    Ok(())
}

pub fn process_delete(accounts: &[AccountInfo]) -> ProgramResult {
    let name_account = next_account_info(accounts_iter)?;
    let name_owner = next_account_info(accounts_iter)?;
    let refund_target = next_account_info(accounts_iter)?;

    let name_record_header = NameRecordHeader::unpack_from_slice(&name_account.data.borrow())?;

    if !name_owner.is_signer || name_record_header.owner != *name_owner.key {
        return Err(ProgramError::InvalidArgument);
    }

    write_data(name_account, &vec![0; name_account.data_len()], 0);

    let source_amount: &mut u64 = &mut name_account.lamports.borrow_mut();
    let dest_amount: &mut u64 = &mut refund_target.lamports.borrow_mut();
    *dest_amount = dest_amount.saturating_add(*source_amount);
    *source_amount = 0;
    Ok(())
}

RecordInstruction::Write { offset, data } => {
    let data_info = next_account_info(account_info_iter)?;

    let start = RecordData::WRITABLE_START_INDEX + offset as usize;
    let end = start + data.len();
    data_info.data.borrow_mut()[start..end].copy_from_slice(data);
    Ok(())
}

fn pay_creator_fees<'a>(
    metadata_info: &AccountInfo<'a>, size: u64, is_native: bool,
) -> Result<u64, ProgramError> {
    let metadata = try_from_slice_unchecked::<Metadata>(&metadata_info.try_borrow_data()?)?;
    let fees = metadata.data.seller_fee_basis_points;
    let total_fee = (fees as u64) * size / 10000;
    let remaining_size = size - total_fee;

    match metadata.data.creators {
        Some(creators) => {
            for creator in creators {
                let creator_fee = creator.share as u64 * total_fee / 100;
                remaining_fee = remaining_fee - creator_fee;
            }
        }
        None => {}
    }
    Ok(remaining_size + remaining_fee)
}

fn process_realloc(accounts: &[AccountInfo], space: u32) -> ProgramResult {
    let name_account = next_account_info(accounts_iter)?;

    let new_space = NameRecordHeader::LEN + space as usize;
    name_account.realloc(new_space, false)?;
    Ok(())
}

pub fn process_recover_nested(program_id: &Pubkey, accounts: &[AccountInfo]) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let nested_associated_token_account_info = next_account_info(account_info_iter)?;
    let nested_token_mint_info = next_account_info(account_info_iter)?;
    let destination_associated_token_account_info = next_account_info(account_info_iter)?;
    let owner_associated_token_account_info = next_account_info(account_info_iter)?;
    let owner_token_mint_info = next_account_info(account_info_iter)?;
    let wallet_account_info = next_account_info(account_info_iter)?;
    let spl_token_program_info = next_account_info(account_info_iter)?;
    let spl_token_program_id = spl_token_program_info.key;

    if !wallet_account_info.is_signer {
        msg!("Wallet of the owner associated token account must sign");
        return Err(ProgramError::MissingRequiredSignature);
    }

    if owner_token_mint_info.owner != spl_token_program_id {
        return Err(ProgramError::IllegalOwner);
    }

    if owner_associated_token_account_info.owner != spl_token_program_id {
        return Err(ProgramError::IllegalOwner);
    }
    let owner_account_data = owner_associated_token_account_info.data.borrow();
    let owner_account = StateWithExtensions::<Account>::unpack(&owner_account_data)?;
    if owner_account.base.owner != *wallet_account_info.key {
        return Err(AssociatedTokenAccountError::InvalidOwner.into());
    }

    if nested_associated_token_account_info.owner != spl_token_program_id {
        return Err(ProgramError::IllegalOwner);
    }
    let nested_account_data = nested_associated_token_account_info.data.borrow();
    let nested_account = StateWithExtensions::<Account>::unpack(&nested_account_data)?;
    if nested_account.base.owner != *owner_associated_token_account_info.key {
        return Err(AssociatedTokenAccountError::InvalidOwner.into());
    }

    Ok(())
}

fn process_withdraw_stake(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    user_stake_authority: &Pubkey,
    token_amount: u64,
) -> ProgramResult {
    // FIRST: Burn user's pool tokens (destroys withdrawal authorization)
    Self::token_burn(pool_info.key, token_program_info.clone(),
        user_token_account_info.clone(), pool_mint_info.clone(),
        pool_mint_authority_info.clone(), mint_authority_bump_seed, token_amount)?;

    // SECOND: Split stake from pool to user
    Self::stake_split(pool_info.key, pool_stake_info.clone(),
        pool_stake_authority_info.clone(), stake_authority_bump_seed,
        withdraw_stake, user_stake_info.clone())?;

    // LAST: Assign authorities to user
    Self::stake_authorize(pool_info.key, user_stake_info.clone(),
        pool_stake_authority_info.clone(), stake_authority_bump_seed,
        user_stake_authority, clock_info.clone())?;

    Ok(())
}

fn process_flash_loan(
    program_id: &Pubkey,
    liquidity_amount: u64,
    accounts: &[AccountInfo],
) -> ProgramResult {
    let mut reserve = Reserve::unpack(&reserve_info.data.borrow())?;

    reserve.liquidity.borrow(Decimal::from(liquidity_amount))?;
    Reserve::pack(reserve, &mut reserve_info.data.borrow_mut())?;

    spl_token_transfer(TokenTransferParams {
        source: source_liquidity_info.clone(),
        destination: destination_liquidity_info.clone(),
        amount: liquidity_amount,
        authority: lending_market_authority_info.clone(),
        authority_signer_seeds,
        token_program: token_program_id.clone(),
    })?;

    invoke(
        &Instruction {
            program_id: *flash_loan_receiver_program_id.key,
            accounts: flash_loan_instruction_accounts,
            data,
        },
        &flash_loan_instruction_account_infos[..],
    )?;

    Ok(())
}

pub fn process_collect(program_id: &Pubkey, accounts: &[AccountInfo]) -> ProgramResult {
    let collector_long_token_account: Account = assert_initialized(collector_long_token_account_info)?;
    let collector_short_token_account: Account = assert_initialized(collector_short_token_account_info)?;
    let escrow_account: Account = assert_initialized(escrow_account_info)?;
    let binary_option = BinaryOption::try_from_slice(&binary_option_account_info.data.borrow_mut())?;

    if !binary_option.settled {
        return Err(BinaryOptionError::BetNotSettled.into());
    }

    let reward = if collector_long_token_account.mint == binary_option.winning_side_pubkey {
        collector_long_token_account.amount
    } else if collector_short_token_account.mint == binary_option.winning_side_pubkey {
        collector_short_token_account.amount
    } else {
        return Err(BinaryOptionError::TokenNotFoundInPool.into());
    };

    if reward > 0 {
        let amount = reward
            .checked_mul(escrow_account.amount)
            .ok_or(BinaryOptionError::AmountOverflow)?;
        let amount = amount / binary_option.circulation;
        spl_token_transfer_signed(token_program_info, escrow_account_info,
            collector_account_info, escrow_authority_info, amount, seeds)?;
        binary_option.decrement_supply(reward)?;
    }
    Ok(())
}

fn process_redeem_reserve_collateral(
