pub fn process_init_pool(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    mint_end_slot: Slot,
    decide_end_slot: Slot,
) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let pool_account_info = next_account_info(account_info_iter)?;
    let authority_info = next_account_info(account_info_iter)?;

    let (authority, bump_seed) = Self::authority_id(program_id, pool_account_info.key)?;
    if *authority_info.key != authority {
        return Err(PoolError::InvalidAuthorityAccount.into());
    }

    let mut pool = Pool::try_from_slice(&pool_account_info.data.borrow())?;
    pool.bump_seed = bump_seed;
    pool.mint_end_slot = mint_end_slot;
    pool.decide_end_slot = decide_end_slot;

    borsh::to_writer(&mut pool_account_info.data.borrow_mut()[..], &pool)?;
    Ok(())
}

pub fn process_withdraw_all_token_types(
    program_id: &Pubkey, pool_token_amount: u64,
    minimum_token_a_amount: u64, minimum_token_b_amount: u64,
    accounts: &[AccountInfo],
) -> ProgramResult {
    let token_swap = SwapVersion::unpack(&swap_info.data.borrow())?;
    Self::check_accounts(token_swap.as_ref(), program_id, swap_info, authority_info,
        token_a_info, token_b_info, pool_mint_info, pool_token_program_info, None, None, Some(pool_fee_account_info))?;

    let results = calculator.pool_tokens_to_trading_tokens(
        u128::from(pool_token_amount), u128::from(pool_mint.supply),
        u128::from(token_a.amount), u128::from(token_b.amount), RoundDirection::Floor)?;

    // FIRST: Burn pool tokens (destroy user's LP position)
    Self::token_burn(swap_info.key, pool_token_program_info.clone(),
        source_info.clone(), pool_mint_info.clone(), authority_info.clone(),
        token_swap.bump_seed(), pool_token_amount)?;

    // THEN: Transfer tokens A and B out
    Self::token_transfer(swap_info.key, token_a_program_info.clone(),
        token_a_info.clone(), token_a_mint_info.clone(), dest_a_info.clone(),
        authority_info.clone(), token_swap.bump_seed(), token_a_amount, decimals_a)?;
    Self::token_transfer(swap_info.key, token_b_program_info.clone(),
        token_b_info.clone(), token_b_mint_info.clone(), dest_b_info.clone(),
        authority_info.clone(), token_swap.bump_seed(), token_b_amount, decimals_b)?;
    Ok(())
}

fn process_exchange(program_id: &Pubkey, accounts: &[AccountInfo]) -> ProgramResult {
    check_owner(original_account_info, original_token_program.key)?;
    check_owner(original_mint_info, original_token_program.key)?;
    check_owner(new_escrow_info, new_token_program.key)?;
    check_owner(new_account_info, new_token_program.key)?;
    check_owner(new_mint_info, new_token_program.key)?;

    let (token_amount, decimals) = {
        let original_account = StateWithExtensions::<Account>::unpack(&original_account_data)?;
        let new_escrow = StateWithExtensions::<Account>::unpack(&new_escrow_data)?;
        if new_escrow.base.amount < token_amount {
            return Err(ProgramError::InsufficientFunds);
        }
        (original_account.base.amount, original_mint.base.decimals)
    };

    burn_original_tokens(original_token_program.clone(), original_account_info.clone(),
        original_mint_info.clone(), original_transfer_authority_info.clone(),
        account_info_iter.as_slice(), token_amount, decimals)?;

    transfer_new_tokens(new_token_program.clone(), new_escrow_info.clone(),
        new_mint_info.clone(), new_account_info.clone(), new_transfer_authority_info.clone(),
        &authority_seeds, token_amount, decimals)?;
    Ok(())
}

pub fn process_collect(program_id: &Pubkey, accounts: &[AccountInfo],
    bump_seed: u8,
) -> ProgramResult {
    let escrow_owner_key = Pubkey::create_program_address(
        &[long_token_mint_info.key.as_ref(), short_token_mint_info.key.as_ref(),
          token_program_info.key.as_ref(), program_id.as_ref(), &[bump_seed]],
        program_id,
    )?;
    let seeds = &[long_token_mint_info.key.as_ref(), short_token_mint_info.key.as_ref(),
        token_program_info.key.as_ref(), program_id.as_ref(), &[bump_seed]];

    assert_keys_equal(escrow_owner_key, *escrow_authority_info.key)?;

    if reward > 0 {
        let amount = reward.checked_mul(escrow_account.amount)
            .ok_or(BinaryOptionError::AmountOverflow)?;
        let amount = amount / binary_option.circulation;
        spl_token_transfer_signed(token_program_info, escrow_account_info,
            collector_account_info, escrow_authority_info, amount, seeds)?;
    }
    Ok(())
}

fn process_propose(program_id: &Pubkey, accounts: &[AccountInfo],
    tokens_to_mint: u64, acceptance_criteria: AcceptanceCriteria,
) -> ProgramResult {
    let (mint_address, mint_bump_seed) = get_mint_address_with_seed(feature_proposal_info.key);
    if mint_address != *mint_info.key {
        return Err(ProgramError::InvalidArgument);
    }
    let (distributor_token_address, distributor_token_bump_seed) =
        get_distributor_token_address_with_seed(feature_proposal_info.key);
    if distributor_token_address != *distributor_token_info.key {
        return Err(ProgramError::InvalidArgument);
    }

    invoke(
        &system_instruction::create_account(funder_info.key, feature_proposal_info.key,
            rent.minimum_balance(FeatureProposal::get_packed_len()),
            FeatureProposal::get_packed_len() as u64, program_id),
        &[funder_info.clone(), feature_proposal_info.clone(), system_program_info.clone()],
    )?;

    invoke_signed(
        &system_instruction::create_account(funder_info.key, mint_info.key,
            rent.minimum_balance(Mint::get_packed_len()), Mint::get_packed_len() as u64, &spl_token::id()),
        &[funder_info.clone(), mint_info.clone(), system_program_info.clone()],
        &[mint_signer_seeds],
    )?;

    invoke(
        &spl_token::instruction::initialize_mint(&spl_token::id(), mint_info.key,
            mint_info.key, None, spl_token::native_mint::DECIMALS)?,
        &[mint_info.clone(), spl_token_program_info.clone(), rent_sysvar_info.clone()],
    )?;

    invoke_signed(
        &spl_token::instruction::mint_to(&spl_token::id(), mint_info.key,
            distributor_token_info.key, mint_info.key, &[], tokens_to_mint)?,
        &[mint_info.clone(), distributor_token_info.clone(), spl_token_program_info.clone()],
        &[mint_signer_seeds],
    )?;
    Ok(())
}

pub fn process_deposit_all_token_types(
    program_id: &Pubkey,
    pool_token_amount: u64,
    accounts: &[AccountInfo],
) -> ProgramResult {
    let token_swap = SwapVersion::unpack(&swap_info.data.borrow())?;
    let calculator = &token_swap.swap_curve().calculator;

    let token_a = Self::unpack_token_account(token_a_info, token_swap.token_program_id())?;
    let token_b = Self::unpack_token_account(token_b_info, token_swap.token_program_id())?;
    let pool_mint = Self::unpack_mint(pool_mint_info, token_swap.token_program_id())?;

    let results = calculator
        .pool_tokens_to_trading_tokens(
            pool_token_amount as u128,
            pool_mint.supply as u128,
            token_a.amount as u128,
            token_b.amount as u128,
            RoundDirection::Ceiling,
        )
        .ok_or(SwapError::ZeroTradingTokens)?;

    let token_a_amount = results.token_a_amount as u64;
    let token_b_amount = results.token_b_amount as u64;

    Self::token_transfer(swap_info.key, token_a_program_info.clone(),
        source_a_info.clone(), token_a_mint_info.clone(), token_a_info.clone(),
        user_transfer_authority_info.clone(), token_swap.bump_seed(),
        token_a_amount, decimals_a)?;

    Ok(())
}

pub fn process_swap(
    program_id: &Pubkey,
    amount_in: u64,
    accounts: &[AccountInfo],
) -> ProgramResult {
    let token_swap = SwapVersion::unpack(&swap_info.data.borrow())?;
    let source_account = Self::unpack_token_account(swap_source_info, token_swap.token_program_id())?;
    let dest_account = Self::unpack_token_account(swap_destination_info, token_swap.token_program_id())?;

    let result = token_swap
        .swap_curve()
        .swap(
            amount_in as u128,
            source_account.amount as u128,
            dest_account.amount as u128,
            trade_direction,
            token_swap.fees(),
        )
        .ok_or(SwapError::ZeroTradingTokens)?;

    let source_amount_swapped = result.source_amount_swapped as u64;
    let amount_out = result.destination_amount_swapped as u64;

    let pool_token_amount = token_swap
        .swap_curve()
        .calculator
        .withdraw_single_token_type_exact_out(
            result.owner_fee,
            swap_token_a_amount,
            swap_token_b_amount,
            pool_mint.supply as u128,
            trade_direction,
            RoundDirection::Floor,
        )
        .ok_or(SwapError::FeeCalculationFailure)?;

    let host_fee = token_swap.fees().host_fee(pool_token_amount)
        .ok_or(SwapError::FeeCalculationFailure)?;
    pool_token_amount = pool_token_amount - host_fee;

    Ok(())
}

fn process_deposit_reserve_liquidity(
    program_id: &Pubkey,
    liquidity_amount: u64,
    accounts: &[AccountInfo],
) -> ProgramResult {
    if liquidity_amount == 0 {
        return Err(LendingError::InvalidAmount.into());
    }

    let lending_market = LendingMarket::unpack(&lending_market_info.data.borrow())?;
    if lending_market_info.owner != program_id {
        return Err(LendingError::InvalidAccountOwner.into());
    }

    let mut reserve = Reserve::unpack(&reserve_info.data.borrow())?;
    if reserve_info.owner != program_id {
        return Err(LendingError::InvalidAccountOwner.into());
    }
    if &reserve.lending_market != lending_market_info.key {
        return Err(LendingError::InvalidAccountInput.into());
    }
    if &reserve.liquidity.supply_pubkey == source_liquidity_info.key {
        return Err(LendingError::InvalidAccountInput.into());
    }
    if reserve.last_update.is_stale(clock.slot)? {
        return Err(LendingError::ReserveStale.into());
    }

    let collateral_amount = reserve.deposit_liquidity(liquidity_amount)?;
    reserve.last_update.mark_stale();
    Reserve::pack(reserve, &mut reserve_info.data.borrow_mut())?;

    spl_token_transfer(TokenTransferParams {
        source: source_liquidity_info.clone(),
        destination: reserve_liquidity_supply_info.clone(),
        amount: liquidity_amount,
        authority: user_transfer_authority_info.clone(),
        authority_signer_seeds: &[],
        token_program: token_program_id.clone(),
    })?;

    Ok(())
}

fn check_pool_stake_authority_address(
    program_id: &Pubkey, pool_key: &Pubkey, authority_key: &Pubkey,
) -> Result<u8, ProgramError> {
    let (expected_authority, bump) = crate::find_pool_stake_authority_address(program_id, pool_key);
    if expected_authority != *authority_key {
        Err(SinglePoolError::InvalidPoolStakeAuthority.into())
    } else {
        Ok(bump)
    }
}

pub fn process_swap(
    program_id: &Pubkey,
    amount_in: u64,
    minimum_amount_out: u64,
    accounts: &[AccountInfo],
) -> ProgramResult {
    let token_swap = SwapVersion::unpack(&swap_info.data.borrow())?;

    // FIRST: Transfer user's source tokens INTO the pool
    Self::token_transfer(
        swap_info.key, source_token_program_info.clone(),
        source_info.clone(), source_token_mint_info.clone(),
        swap_source_info.clone(), user_transfer_authority_info.clone(),
        token_swap.bump_seed(), source_transfer_amount, source_mint_decimals,
    )?;

    // THEN: Transfer pool's destination tokens OUT to user
    Self::token_transfer(
        swap_info.key, destination_token_program_info.clone(),
        swap_destination_info.clone(), destination_token_mint_info.clone(),
        destination_info.clone(), authority_info.clone(),
        token_swap.bump_seed(), destination_transfer_amount, destination_mint_decimals,
    )?;

    Ok(())
}

fn process_modify_reserve_config(
    program_id: &Pubkey, new_config: ReserveConfig, accounts: &[AccountInfo],
) -> ProgramResult {
    let mut reserve = Reserve::unpack(&reserve_info.data.borrow_mut())?;
    reserve.config = new_config;
    Reserve::pack(reserve, &mut reserve_info.data.borrow_mut())?;
    Ok(())
}

fn process_refresh_obligation(program_id: &Pubkey, accounts: &[AccountInfo]) -> ProgramResult {
    let mut obligation = Obligation::unpack(&obligation_info.data.borrow())?;

    let mut deposited_value = Decimal::zero();
    let mut borrowed_value = Decimal::zero();
    let mut allowed_borrow_value = Decimal::zero();

    for (index, collateral) in obligation.deposits.iter_mut().enumerate() {
        let deposit_reserve = Reserve::unpack(&deposit_reserve_info.data.borrow())?;
        if deposit_reserve.last_update.is_stale(clock.slot)? {
            return Err(LendingError::ReserveStale.into());
        }

        let decimals = 10u64
            .checked_pow(deposit_reserve.liquidity.mint_decimals as u32)
            .ok_or(LendingError::MathOverflow)?;

        let market_value = deposit_reserve
            .collateral_exchange_rate()?
            .decimal_collateral_to_liquidity(collateral.deposited_amount.into())?
            .try_mul(deposit_reserve.liquidity.market_price)?
            .try_div(decimals)?;

        let loan_to_value_rate = Rate::from_percent(deposit_reserve.config.loan_to_value_ratio);
        deposited_value = deposited_value.try_add(market_value)?;
        allowed_borrow_value = allowed_borrow_value.try_add(market_value.try_mul(loan_to_value_rate)?)?;
    }

    obligation.deposited_value = deposited_value;
    obligation.borrowed_value = borrowed_value;
    obligation.last_update.update_slot(clock.slot);
    Obligation::pack(obligation, &mut obligation_info.data.borrow_mut())?;
    Ok(())
}

fn process_accept_offer(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    maker_size: u64,
    taker_size: u64,
) -> ProgramResult {
    let maker_src_token_account = spl_token::state::Account::unpack(&maker_src_account.data.borrow())?;

    if maker_src_token_account.delegated_amount != maker_pay_size {
        return Err(ProgramError::InvalidAccountData);
    }
    if maker_src_token_account.delegate != COption::Some(authority_key) {
        return Err(ProgramError::InvalidAccountData);
    }

    // FIRST: Transfer from maker to taker (uses PDA delegate)
    invoke_signed(
        &spl_token::instruction::transfer(
            token_program_info.key, maker_src_account.key,
            taker_dst_account.key, transfer_authority.key, &[], maker_pay_size,
        )?,
        &[maker_src_account.clone(), taker_dst_account.clone(),
          transfer_authority.clone(), token_program_info.clone()],
        &[seeds],
    )?;

    // THEN: Transfer from taker to maker (taker signs directly)
    invoke(
        &spl_token::instruction::transfer(
            token_program_info.key, taker_src_account.key,
            maker_dst_account.key, taker_wallet.key, &[], taker_pay_size,
        )?,
        &[taker_src_account.clone(), maker_dst_account.clone(),
          taker_wallet.clone(), token_program_info.clone()],
    )?;
    Ok(())
}

